 ('/profile','PUT','Modifica el perfil del usuario'),
 ('/profile/fetch-by-user-id','GET','Listado de perfiles'),
 ('/profile','DELETE','Elimina el perfil del usuario'),
 ('/master/get-terms-and-conditions','GET','Muestra los términos y condiciones al usuario'),
 ('/master/get-app-settings','GET','Ajustes de Configuración'),
 ('/scan/get-additives-from-image','POST','Detecta aditivos desde un texto y devuelve su reporte de toxicidad'),
